36	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
37	type Event struct {
38		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执 | 发运 | 接收 | 改址
39		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站；发运时为源站，接收时为目的站；改址时为源站，包裹不移动）
40		Time       time.Time `json:"time"`                 // 发生时间
41		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销/接收/改址请求号（收件、出站、发运记录为空）
42		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）、发运/接收源站（仅发运、接收记录有）或改址前有效目的站（仅改址记录有）
43		To         string    `json:"to,omitempty"`         // 发运/接收目的站（仅发运、接收记录有）或改址后的新目的站（仅改址记录有）
44		Shipment   string    `json:"shipment,omitempty"`   // 运输单号（仅发运、接收、改址记录有）
45		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）、撤销原因（仅撤销回执记录有）或改址原因（仅改址记录有）
46		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
47		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
48		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
49		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
50		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
51		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
52		Incident string `json:"incident,omitempty"`
53		Note     string `json:"note,omitempty"`
54	}
55	
56	// Parcel 是一件包裹的台账信息。
57	type Parcel struct {
58		ID         string    `json:"id"`
59		Station    string    `json:"station"`    // 当前归属站点
60		Status     string    `json:"status"`     // 当前状态
61		Registered time.Time `json:"registered"` // 收件时间
62		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
63	}
64	
65	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
66	type HandoffResult struct {
67		Request    string    `json:"request"`
68		From       string    `json:"from"`
69		To         string    `json:"to"`
70		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
71		Time       time.Time `json:"time"`
72		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
73	}
74	
75	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
76	type ReturnResult struct {
77		Request string    `json:"request"` // 退回请求号
78		Handoff string    `json:"handoff"` // 被退回的原交接请求号
79		From    string    `json:"from"`    // 退回源站（原交接目的站）
80		To      string    `json:"to"`      // 退回目的站（原交接源站）
81		Reason  string    `json:"reason"`
82		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
83		Time    time.Time `json:"time"`
84	}
85	
86	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
87	// 台账级 Receipts 结果表与撤销记录共同保留）。
88	type ReceiptEntry struct {
89		Request string    `json:"request"`          // 回执请求号
90		Result  string    `json:"result"`           // 签收 | 失败
91		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
92		Time    time.Time `json:"time"`
93		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
94		RevokedBy string `json:"revokedBy,omitempty"`
95	}
96	
97	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
98	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
99	type BatchResult struct {
100		Batch    string                   `json:"batch"`
101		Station  string                   `json:"station"`  // 出发站
102		Courier  string                   `json:"courier"`  // 配送员
103		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
104		Time     time.Time                `json:"time"`     // 出站时间
105		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
106		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
107		AbortedBy string `json:"abortedBy,omitempty"`
108		// TransferredBy 为把最后待配送件转走、永久关闭该批次为“已转交”的续接请求号
109		// （尚未永久转交为空）。途中分批续接期间该批次仍配送中，各次续接记录见 Transfers；
110		// 转走最后一件待配送件时才在此置位，与中止互斥，批次永久关闭、不得复用。
111		TransferredBy string `json:"transferredBy,omitempty"`
112		// Transfers 为该批次作为原批次发生过的各次续接的请求号，按提交顺序追加。
113		// 分批续接只转走部分待配送件：原批次保留件继续由原配送员按原批次配送，
114		// 故批次仍开放、仍可回执、中止或再次续接；旧版数据文件只有最后一次（整批）
115		// 续接的 transferredBy，载入时迁移到本列表。
116		Transfers []string `json:"transfers,omitempty"`
117		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
118		// 与创建本批次的续接请求号（普通出站批次为空）。
119		RelayedFrom  string `json:"relayedFrom,omitempty"`
120		RelayRequest string `json:"relayRequest,omitempty"`
121	}
122	
123	// openParcels 返回该批次当前仍由本批次配送的待配送成员（无有效回执且未转交），
124	// 按原成员顺序。载入校验保证 Transfers 引用的续接请求均存在。
125	func (b *BatchResult) openParcels(ledger *ledgerFile) []string {
126		out := make([]string, 0, len(b.Parcels))
127		for _, pid := range b.Parcels {
128			if e, done := b.Receipts[pid]; done && e.RevokedBy == "" {
129				continue // 已有有效回执
130			}
131			transferred := false
132			for _, req := range b.Transfers {
133				if t := ledger.Transfers[req]; t != nil {
134					for _, id := range t.Parcels {
135						if id == pid {
136							transferred = true
137							break
138						}
139					}
140				}
141				if transferred {
142					break
143				}
144			}
145			if !transferred {
146				out = append(out, pid)
147			}
148		}
149		return out
150	}
151	
152	// Effective 返回批次当前有效（未撤销）的回执数量。
153	func (b *BatchResult) Effective() int {
154		n := 0
155		for _, e := range b.Receipts {
156			if e != nil && e.RevokedBy == "" {
157				n++
158			}
159		}
160		return n
161	}
162	
163	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
164	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
165	
166	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
167	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
168	type ReceiptResult struct {
169		Request string    `json:"request"` // 回执请求号
170		Batch   string    `json:"batch"`   // 所属配送批次号
171		Parcel  string    `json:"parcel"`  // 包裹编号
172		Result  string    `json:"result"`  // 签收 | 失败
173		Reason  string    `json:"reason,omitempty"`
174		Time    time.Time `json:"time"`
175		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
176		RevokedBy string `json:"revokedBy,omitempty"`
177	}
178	
179	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
180	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
181	type FreezeResult struct {
182		Incident string    `json:"incident"` // 异常单号
183		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
184		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
185		Reason   string    `json:"reason"`   // 清理后的冻结原因
186		Time     time.Time `json:"time"`     // 冻结时间
187		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
188		ReleasedBy string `json:"releasedBy,omitempty"`
189	}
190	
191	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
192	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
193	type UnfreezeResult struct {
194		Request  string    `json:"request"`  // 解除请求号
195		Incident string    `json:"incident"` // 被解除的异常单号
196		Parcel   string    `json:"parcel"`   // 对应包裹编号
197		Note     string    `json:"note"`     // 清理后的处理说明
198		Time     time.Time `json:"time"`     // 解除时间
199	}
200	
201	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
202	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
203	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
204	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
205	type AbortResult struct {
206		Request string    `json:"request"` // 中止请求号
207		Batch   string    `json:"batch"`   // 被中止的配送批次号
208		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
209		Reason  string    `json:"reason"`  // 清理后的中止原因
210		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
211		Time    time.Time `json:"time"`    // 中止时间
212	}
213	
214	// TransferResult 记录一次成功的配送途中续接，用于续接请求号去重与结果重放。
215	// 续接表示原配送员把原批次部分或全部尚未回执的包裹在配送途中交给另一配送员：
216	// 新批次按原成员顺序接纳本次选中件继续配送，包裹保持“配送中”及原站点；
217	// 未选中的余件继续留在原批次由原配送员配送。只转交部分待配送件时原批次仍
218	// 开放（仍配送中，可继续回执、中止或再次续接），转走最后一件待配送件时原批次
219	// 才永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他业务
220	// 编号同名；失败的首次续接不占用请求号。
221	type TransferResult struct {
222		Request     string    `json:"request"`     // 续接请求号
223		FromBatch   string    `json:"fromBatch"`   // 原批次号
224		ToBatch     string    `json:"toBatch"`     // 新批次号
225		Station     string    `json:"station"`     // 出发站（沿用原批次）
226		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
227		ToCourier   string    `json:"toCourier"`   // 新配送员
228		Reason      string    `json:"reason"`      // 清理后的续接原因
229		Parcels     []string  `json:"parcels"`     // 本次转交集合，按原批次成员顺序
230		Time        time.Time `json:"time"`        // 接手时间
231		// Explicit 为 true 表示本次续接显式选择了包裹集合；false 表示不选成员、
232		// 取当时全部无有效回执且未转交的待配送件（旧版整批续接记录没有该字段，
233		// 按不选成员处理）。
234		Explicit bool `json:"explicit,omitempty"`
235	}
236	
237	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
238	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
239	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
240	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
241	// 失败的首次撤销不占用请求号。
242	type RevokeResult struct {
243		Request string    `json:"request"` // 撤销请求号
244		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
245		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
246		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
247		Reason  string    `json:"reason"`  // 清理后的撤销原因
248		Time    time.Time `json:"time"`    // 撤销时间
249	}
250	
251	// ShipmentResult 记录一次成功的站间发运，用于运输单号去重、结果重放与运输单查询。
252	// 发运表示整单包裹已离开源站、尚未到达目的站：整单转为“站间在途”，归属站点暂记
253	// 源站，成员按首次提交顺序保存，保存后不可修改。运输单号独立于已有各类编号，
254	// 接收后也不释放；失败的首次发运不占用运输单号。
255	type ShipmentResult struct {
256		Shipment string    `json:"shipment"` // 运输单号
257		From     string    `json:"from"`     // 源站
258		To       string    `json:"to"`       // 目的站
259		Parcels  []string  `json:"parcels"`  // 成员，按首次提交顺序
260		Time     time.Time `json:"time"`     // 发运时间
261		// ReceivedBy 为使该运输单达到全部接收的接收请求号（尚未全部接收为空）；
262		// 全部接收永久生效，运输单号不释放。分批到站时可能经历多次接收，
263		// 每次接收记录于接收结果表，是否全部接收按各次接收事实统计。
264		ReceivedBy string `json:"receivedBy,omitempty"`
265		// Reroutes 为该运输单各次改址的改址请求号，按提交顺序追加（未改址为空）。
266		// 改址只变更当时全部未收件的有效目的站：原目的站、成员、发运结果与已有
267		// 接收事实永久保留。旧版数据文件没有该字段，按未改址处理。
268		Reroutes []string `json:"reroutes,omitempty"`
269	}
270	
271	// ReceiveResult 记录一次成功的到站接收，用于接收请求号去重与结果重放。
272	// 接收表示运输单的一批成员已到达目的站：按发运保存顺序将本次成员改归目的站、
273	// 恢复在站；全部成员到齐后运输单永久标记为已接收。接收请求号与运输单号及已有
274	// 各类编号分属独立去重范围，允许同名；失败的首次接收不占用请求号。
275	type ReceiveResult struct {
276		Request  string    `json:"request"`  // 接收请求号
277		Shipment string    `json:"shipment"` // 被接收的运输单号
278		Station  string    `json:"station"`  // 接收站点（即运输单目的站）
279		Parcels  []string  `json:"parcels"`  // 本次接收的成员，按发运保存顺序
280		Time     time.Time `json:"time"`     // 接收时间
281		// Explicit 为 true 表示本次接收显式选择了包裹集合；false 表示不选成员、
282		// 接收当时全部尚未接收件（旧版整单接收记录没有该字段，按不选成员处理）。
283		Explicit bool `json:"explicit,omitempty"`
284	}
285	
286	// RerouteResult 记录一次成功的运输途中改址，用于改址请求号去重与结果重放。
287	// 改址表示一张运输单当前全部未收件改送另一目的站：不另建运输单、不重新发运，
288	// 成员仍归源站、保持站间在途及作业限制，只变更余件的有效目的站；原成员、发运
289	// 结果、已有接收事实与轨迹永久保留。集合为受理时全部未收件，按发运保存顺序。
290	// 改址请求号独立去重，可与运输单号及其他业务编号同名；失败的首次改址不占用请求号。
291	type RerouteResult struct {
292		Request  string    `json:"request"`  // 改址请求号
293		Shipment string    `json:"shipment"` // 被改址的运输单号
294		From     string    `json:"from"`     // 改址前的有效目的站（首次为运输单原目的站）
295		To       string    `json:"to"`       // 新目的站（不同于改址前有效目的站与源站）
296		Reason   string    `json:"reason"`   // 清理后的改址原因
297		Parcels  []string  `json:"parcels"`  // 受理时全部未收件，按发运保存顺序
298		Time     time.Time `json:"time"`     // 改址时间
299	}
300	
301	// ledgerFile 是本地数据文件的磁盘结构。
302	type ledgerFile struct {
303		Version   int                        `json:"version"`
304		Parcels   map[string]*Parcel         `json:"parcels"`
305		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
306		Returns   map[string]*ReturnResult   `json:"returns"`
307		Batches   map[string]*BatchResult    `json:"batches"`
308		Receipts  map[string]*ReceiptResult  `json:"receipts"`
309		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
310		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
311		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
312		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
313		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
314		Shipments map[string]*ShipmentResult `json:"shipments"` // 以运输单号为键（含已接收的运输单，永久保留）
315		Receives  map[string]*ReceiveResult  `json:"receives"`  // 以接收请求号为键
316		Reroutes  map[string]*RerouteResult  `json:"reroutes"`  // 以改址请求号为键
317	}
318	
319	// Store 是一个数据文件对应的包裹站点交接台账。
320	type Store struct {
321		path string
322		data ledgerFile
323	}
324	
325	var (
326		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
327		ErrCorrupt = errors.New("数据文件已损坏")
328		// ErrNotFound 表示包裹编号在台账中不存在。
329		ErrNotFound = errors.New("包裹不存在")
330	)
331	
332	// Open 打开（或在文件不存在时建立）一个本地台账。
333	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
334	func Open(path string) (*Store, error) {
335		s := &Store{path: path}
336		raw, err := os.ReadFile(path)
337		if err != nil {
338			if os.IsNotExist(err) {
339				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
340					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
341					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
342					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}, Shipments: map[string]*ShipmentResult{},
343					Receives: map[string]*ReceiveResult{}, Reroutes: map[string]*RerouteResult{}}
344				return s, nil
345			}
346			return nil, fmt.Errorf("读取数据文件失败: %w", err)
347		}
348		if len(bytes.TrimSpace(raw)) == 0 {
349			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
350		}
351		if err := json.Unmarshal(raw, &s.data); err != nil {
352			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
353		}
354		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
355			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
356		}
357		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
358		if s.data.Returns == nil {
359			s.data.Returns = map[string]*ReturnResult{}
360		}
361		if s.data.Batches == nil {
362			s.data.Batches = map[string]*BatchResult{}
363		}
364		if s.data.Receipts == nil {
365			s.data.Receipts = map[string]*ReceiptResult{}
366		}
367		if s.data.Freezes == nil {
368			s.data.Freezes = map[string]*FreezeResult{}
369		}
370		if s.data.Unfreezes == nil {
371			s.data.Unfreezes = map[string]*UnfreezeResult{}
372		}
373		if s.data.Aborts == nil {
374			s.data.Aborts = map[string]*AbortResult{}
375		}
376		if s.data.Transfers == nil {
377			s.data.Transfers = map[string]*TransferResult{}
378		}
379		if s.data.Revokes == nil {
380			s.data.Revokes = map[string]*RevokeResult{}
381		}
382		// 早期版本的数据文件没有 shipments/receives 字段：按空表处理，无需手工修改。
383		if s.data.Shipments == nil {
384			s.data.Shipments = map[string]*ShipmentResult{}
385		}
386		if s.data.Receives == nil {
387			s.data.Receives = map[string]*ReceiveResult{}
388		}
389		// 早期版本的数据文件没有 reroutes 字段：按空表处理（各运输单均未改址），无需手工修改。
390		if s.data.Reroutes == nil {
391			s.data.Reroutes = map[string]*RerouteResult{}
392		}
393		for _, b := range s.data.Batches {
394			if b != nil && b.Receipts == nil {
395				b.Receipts = map[string]*ReceiptEntry{}
396			}
397		}
398		// 早期版本的续接一次转走全部未回执件，原批次只用 transferredBy 记录最后一次
399		// （也是唯一一次）续接；现把它迁移到按提交顺序的 transfers 列表，旧有效台账
400		// 无需手工修改即可直接使用。
401		for _, b := range s.data.Batches {
402			if b == nil || len(b.Transfers) > 0 {
403				continue
404			}
405			if b.TransferredBy != "" {
406				b.Transfers = []string{b.TransferredBy}
407			}
408		}
409		if err := s.data.validate(); err != nil {
410			return nil, err
411		}
412		return s, nil
413	}
414	
415	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
416	func (l *ledgerFile) validate() error {
417		for id, p := range l.Parcels {
418			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
419				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
420			}
421			switch p.Status {
422			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
423			default:
424				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
425			}
426			for i, e := range p.Trail {
427				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
428					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
429				}
430				if e.Op == "退回" {
431					if e.Request == "" || e.Reason == "" || e.From == "" {
432						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
433					}
434					if _, ok := l.Handoffs[e.RefRequest]; !ok {
435						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
436					}
437				}
438				if e.Op == "出站" {
439					if e.Batch == "" || e.Courier == "" {
440						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
441					}
442					if _, ok := l.Batches[e.Batch]; !ok {
443						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
444					}
445				}
446				if e.Op == "回执" {
447					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
448						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
449					}
450					if e.Result == resultFailed && e.Reason == "" {
451						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
452					}
453					if _, ok := l.Batches[e.Batch]; !ok {
454						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
455					}
456				}
457				if e.Op == "撤销回执" {
458					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
459						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
460					}
461					b, ok := l.Batches[e.Batch]
462					if !ok || b == nil {
463						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
464					}
465					if e.Station != b.Station {
466						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
467							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
468					}
469					rv, ok := l.Revokes[e.Request]
470					if !ok || rv == nil {
471						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
472					}
473					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
474						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
475					}
476				}
477				if e.Op == "收回" {
478					if e.Batch == "" || e.Request == "" || e.Reason == "" {
479						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
480					}
481					a, ok := l.Aborts[e.Request]
482					if !ok || a == nil {
483						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
484					}
485					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
486						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
487					}
488					inAbort := false
489					for _, pid := range a.Parcels {
490						if pid == id {
491							inAbort = true
492							break
493						}
494					}
495					if !inAbort {
496						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
497					}
498				}
499				if e.Op == "续接" {
500					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
501						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
502					}
503					t, ok := l.Transfers[e.Request]
504					if !ok || t == nil {
505						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
506					}
507					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
508						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
509						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
510					}
511					inTransfer := false
512					for _, pid := range t.Parcels {
513						if pid == id {
514							inTransfer = true
515							break
516						}
517					}
518					if !inTransfer {
519						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
520					}
521				}
522				if e.Op == "发运" {
523					if e.Shipment == "" || e.From == "" || e.To == "" {
524						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
525					}
526					sh, ok := l.Shipments[e.Shipment]
527					if !ok || sh == nil {
528						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
529					}
530					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
531						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
532					}
533					inShipment := false
534					for _, pid := range sh.Parcels {
535						if pid == id {
536							inShipment = true
537							break
538						}
539					}
540					if !inShipment {
541						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
542					}
543				}
544				if e.Op == "接收" {
545					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
546						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
547					}
548					rv, ok := l.Receives[e.Request]
549					if !ok || rv == nil {
550						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)
551					}
552					if rv.Shipment != e.Shipment || rv.Station != e.Station || e.Station != e.To || !rv.Time.Equal(e.Time) {
553						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹与接收请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
554					}
555					sh, ok := l.Shipments[e.Shipment]
556					if !ok || sh == nil {
557						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
558					}
559					if sh.From != e.From {
560						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的源站与运输单 %q 记录（源站 %q）不一致",
561							ErrCorrupt, id, i+1, e.Shipment, sh.From)
562					}
563					// 接收目的站必须等于受理时的有效目的站（应用该件此前各次改址后），
564					// 由下方按保存顺序的生命周期校验核对。
565					inReceive := false
566					for _, pid := range rv.Parcels {
567						if pid == id {
568							inReceive = true
569							break
570						}
571					}
572					if !inReceive {
573						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹不在接收请求 %q 的成员集合中", ErrCorrupt, id, i+1, e.Request)
574					}
575				}
576				if e.Op == "改址" {
577					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" || e.Reason == "" {
578						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹缺少运输单号、改址请求号、前后目的站或原因", ErrCorrupt, id, i+1)
579					}
580					r, ok := l.Reroutes[e.Request]
581					if !ok || r == nil {
582						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹引用了不存在的改址请求 %q", ErrCorrupt, id, i+1, e.Request)
583					}
584					if r.Shipment != e.Shipment || r.From != e.From || r.To != e.To || r.Reason != e.Reason || !r.Time.Equal(e.Time) {
585						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹与改址请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
586					}
587					inReroute := false
588					for _, pid := range r.Parcels {
589						if pid == id {
590							inReroute = true
591							break
592						}
593					}
594					if !inReroute {
595						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹不在改址请求 %q 的集合中", ErrCorrupt, id, i+1, e.Request)
596					}
597				}
598				if e.Op == "冻结" {
599					if e.Incident == "" || e.Reason == "" {
600						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
601					}
602					f, ok := l.Freezes[e.Incident]
603					if !ok || f == nil {
604						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
605					}
606					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
607						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
608					}
609				}
610				if e.Op == "解除冻结" {
611					if e.Incident == "" || e.Request == "" || e.Note == "" {
612						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
613					}
614					f, ok := l.Freezes[e.Incident]
615					if !ok || f == nil {
616						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
617					}
618					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
619						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
620					}
621					u, ok := l.Unfreezes[e.Request]
622					if !ok || u == nil || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
623						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
624					}
625				}
626			}
627		}
628		// 站间运输生命周期：按每件轨迹的保存顺序（不按发生时间排序）核对发运、改址与
629		// 接收的配对关系。每张运输单的成员恰有一次对应发运；已接收时恰有一次对应接收
630		// 且位于发运之后；发运后到接收前除改址外不得出现其他作业轨迹；改址记录必须
631		// 按运输单改址列表的保存顺序逐一对应，且接收目的站等于应用此前各次改址后的
632		// 有效目的站；未接收时不得有接收记录，发运（及其后的改址）必须是最后的轨迹。
633		for id, p := range l.Parcels {
634			shipped := make(map[string]bool) // 该包裹轨迹中已出现发运的运输单号
635			var open string                  // 已发运、尚未在轨迹中接收的在途运输单号
636			rerouteIdx := 0                  // 当前在途运输单已在轨迹中出现的改址次数（按运输单改址列表顺序）
637			for i, e := range p.Trail {
638				if open != "" && e.Op != "接收" && e.Op != "改址" {
639					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹（%s）出现在运输单 %q 发运之后、接收之前，在途期间不得有其他作业轨迹",
640						ErrCorrupt, id, i+1, e.Op, open)
641				}
642				switch e.Op {
643				case "发运":
644					if shipped[e.Shipment] {
645						return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹重复发运运输单 %q，每张运输单的成员恰有一次对应发运",
646							ErrCorrupt, id, i+1, e.Shipment)
647					}
648					shipped[e.Shipment] = true
649					open = e.Shipment
650					rerouteIdx = 0
651				case "改址":
652					if open == "" {
653						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹（运输单 %q）位于对应发运之前或接收之后，在途期间才能改址",
654							ErrCorrupt, id, i+1, e.Shipment)
655					}
656					if e.Shipment != open {
657						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
658							ErrCorrupt, id, i+1, e.Shipment, open)
659					}
660					sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
661					if e.Station != sh.From {
662						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹的站点 %q 与运输单 %q 源站 %q 不一致，改址不移动包裹",
663							ErrCorrupt, id, i+1, e.Station, open, sh.From)
664					}
665					if rerouteIdx >= len(sh.Reroutes) || sh.Reroutes[rerouteIdx] != e.Request {
666						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹（改址请求 %q）与运输单 %q 按保存顺序的改址列表不一致",
667							ErrCorrupt, id, i+1, e.Request, open)
668					}
669					rerouteIdx++
670				case "接收":
671					if open == "" {
672						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹（运输单 %q）位于对应发运之前或缺少对应发运",
673							ErrCorrupt, id, i+1, e.Shipment)
674					}
675					if e.Shipment != open {
676						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
677							ErrCorrupt, id, i+1, e.Shipment, open)
678					}
679					// 接收目的站必须等于受理时的有效目的站：原目的站按保存顺序应用
680					// 该件接收前已发生的各次改址（轨迹中前 rerouteIdx 次）。
681					sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
682					eff := sh.To
683					for j := 0; j < rerouteIdx; j++ {
684						eff = l.Reroutes[sh.Reroutes[j]].To // 改址轨迹校验已保证请求存在且非空
685					}
686					if e.To != eff {
687						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的目的站 %q 与运输单 %q 当时有效目的站 %q 不一致",
688							ErrCorrupt, id, i+1, e.To, open, eff)
689					}
690					open = ""
691				}
692			}
693			if open != "" {
694				sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
695				if sh.ReceivedBy != "" {
696					return fmt.Errorf("%w: 包裹 %q 的运输单 %q 已接收（接收请求号 %q），但轨迹缺少对应的接收记录",
697						ErrCorrupt, id, open, sh.ReceivedBy)
698				}
699				// 未收件属于每次改址的集合：轨迹中的改址记录必须覆盖该单全部改址。
700				if rerouteIdx != len(sh.Reroutes) {
701					return fmt.Errorf("%w: 包裹 %q 尚未接收，但缺少运输单 %q 的改址轨迹（轨迹 %d 次，改址列表 %d 次），未收件属于每次改址集合",
702						ErrCorrupt, id, open, rerouteIdx, len(sh.Reroutes))
703				}
704			}
705		}
706		// 当前归属与状态必须由轨迹记录形成：按保存顺序的最后一条轨迹推导应有的归属
707		// 站点与状态，与台账当前值不一致即存在无对应记录的站点或状态改变。接收后的
708		// 合法后续流转（交接、再次发运、回执及其撤销、收回、续接、冻结与解除）会
709		// 产生新的末条轨迹，按新轨迹校验，不因历史接收而把成员固定在目的站。
710		for id, p := range l.Parcels {
711			last := p.Trail[len(p.Trail)-1]
712			var want string
713			switch last.Op {
714			case "收件", "交接", "退回", "收回", "接收", "解除冻结":
715				want = statusInStation
716			case "出站", "续接", "撤销回执":
717				want = statusDelivering
718			case "回执":
719				if last.Result == resultSigned {
720					want = statusSigned
721				} else {
722					want = statusInStation
723				}
724			case "冻结":
725				want = statusFrozen
726			case "发运", "改址":
727				want = statusInTransit // 改址不移动包裹：仍归源站、保持站间在途
728			default:
729				continue // 未知操作不参与推导（逐条校验已兜底）
730			}
731			if p.Station != last.Station || p.Status != want {
732				return fmt.Errorf("%w: 包裹 %q 当前归属 %q、状态 %q 与最后一条轨迹（%s，站点 %q）应形成的归属与状态 %q、%q 不一致",
733					ErrCorrupt, id, p.Station, p.Status, last.Op, last.Station, last.Station, want)
734			}
735		}
736		for req, h := range l.Handoffs {
737			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
738				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
739			}
740			for _, id := range h.Parcels {
741				if _, ok := l.Parcels[id]; !ok {
742					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
743				}
744			}
745			if h.ReturnedBy != "" {
746				r, ok := l.Returns[h.ReturnedBy]
747				if !ok || r == nil || r.Handoff != req {
748					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
749				}
750			}
751		}
752		for req, r := range l.Returns {
753			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
754				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
755				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
756			}
757			h, ok := l.Handoffs[r.Handoff]
758			if !ok || h == nil {
759				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
760			}
761			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
762				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
763			}
764			for _, id := range r.Parcels {
765				if _, ok := l.Parcels[id]; !ok {
766					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
767				}
768			}
769		}
770		for id, b := range l.Batches {
771			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
772				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
773			}
774			seen := make(map[string]bool, len(b.Parcels))
775			for _, pid := range b.Parcels {
776				if seen[pid] {
777					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
778				}
779				seen[pid] = true
780				if _, ok := l.Parcels[pid]; !ok {
781					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
782				}
783			}
784			for pid, e := range b.Receipts {
785				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
786					(e.Result != resultSigned && e.Result != resultFailed) ||
787					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
788					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
789				}
790				rc, ok := l.Receipts[e.Request]
791				if !ok || rc == nil || rc.Batch != id || rc.Parcel != pid {
792					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
793				}
794				if e.RevokedBy != rc.RevokedBy {
795					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
796				}
797			}
798			if b.AbortedBy != "" {
799				a, ok := l.Aborts[b.AbortedBy]
800				if !ok || a == nil || a.Batch != id {
801					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
802				}
803			}
804			if b.TransferredBy != "" {
805				if b.AbortedBy != "" {
806					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
807				}
808				t, ok := l.Transfers[b.TransferredBy]
809				if !ok || t == nil || t.FromBatch != id {
810					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
811				}
812				// 永久转交标记必须是按提交顺序的最后一次续接。
813				if len(b.Transfers) == 0 || b.Transfers[len(b.Transfers)-1] != b.TransferredBy {
814					return fmt.Errorf("%w: 批次 %q 的永久转交标记 %q 不在其按提交顺序的续接列表末尾", ErrCorrupt, id, b.TransferredBy)
815				}
816			}
817			// 各次续接：请求号均存在且源自本批次、不重复；同一件从同一批次不能重复转交；
818			// 转交件不能同时持有该批次的有效回执；永久转交时必须已无待配送件。
819			transferSeen := make(map[string]bool, len(b.Transfers))
820			transferMember := make(map[string]bool, len(b.Parcels))
821			for ti, req := range b.Transfers {
822				if transferSeen[req] {
823					return fmt.Errorf("%w: 批次 %q 的续接列表中请求号 %q 重复", ErrCorrupt, id, req)
824				}
825				transferSeen[req] = true
826				t, ok := l.Transfers[req]
827				if !ok || t == nil {
828					return fmt.Errorf("%w: 批次 %q 的第 %d 次续接引用了不存在的续接请求 %q", ErrCorrupt, id, ti+1, req)
829				}
830				if t.FromBatch != id {
831					return fmt.Errorf("%w: 续接请求 %q 属于原批次 %q，却列入批次 %q 的续接列表", ErrCorrupt, req, t.FromBatch, id)
832				}
833				for _, pid := range t.Parcels {
834					if !seen[pid] {
835						return fmt.Errorf("%w: 续接请求 %q 的包裹 %q 不属于原批次 %q", ErrCorrupt, req, pid, id)
836					}
837					if transferMember[pid] {
838						return fmt.Errorf("%w: 包裹 %q 在批次 %q 下被续接请求 %q 重复转交，同件从同批次只能转交一次",
839							ErrCorrupt, pid, id, req)
840					}
841					transferMember[pid] = true
842					if e, done := b.Receipts[pid]; done && e.RevokedBy == "" {
843						return fmt.Errorf("%w: 批次 %q 的包裹 %q 既有有效回执又被续接请求 %q 转交，二者互斥",
844							ErrCorrupt, id, pid, req)
845					}
846				}
847			}
848			if b.TransferredBy != "" && len(b.openParcels(l)) != 0 {
849				return fmt.Errorf("%w: 批次 %q 已永久转交，但仍有待配送件未转交", ErrCorrupt, id)
850			}
851			if b.RelayedFrom != "" {
852				t, ok := l.Transfers[b.RelayRequest]
853				if !ok || t == nil || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
854					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
855						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
856				}
857			} else if b.RelayRequest != "" {
858				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
859			}
860		}
861		for req, rc := range l.Receipts {
862			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
863				(rc.Result != resultSigned && rc.Result != resultFailed) ||
864				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
865				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
866			}
867			b, ok := l.Batches[rc.Batch]
868			if !ok || b == nil {
869				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
870			}
871			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
872			// 因此该件在批次内必须始终有一条回执条目。
873			e, cur := b.Receipts[rc.Parcel]
874			if !cur {
875				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
876			}
877			if rc.RevokedBy == "" {
878				// 未撤销回执必须仍是该件在该批次的当前有效回执。
879				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
880					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
881				}
882				continue
883			}
884			// 已撤销回执：撤销关联必须存在且回指该回执。
885			rv, ok := l.Revokes[rc.RevokedBy]
886			if !ok || rv == nil || rv.Receipt != req {
887				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
888			}
889			if e.Request == req {
890				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
891				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
892					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
893				}
894			}
895			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
896		}
897		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
898		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
899		for req, rv := range l.Revokes {
900			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
901				rv.Reason == "" || rv.Time.IsZero() {
902				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
903			}
904			rc, ok := l.Receipts[rv.Receipt]
905			if !ok || rc == nil {
906				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
907			}
908			if rc.RevokedBy != req {
909				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
910			}
911			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
912				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
913			}
914			p, ok := l.Parcels[rv.Parcel]
915			if !ok {
916				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
917			}
918			found := false
919			for _, e := range p.Trail {
920				if e.Op == "撤销回执" && e.Request == req {
921					found = true
922					break
923				}
924			}
925			if !found {
926				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
927			}
928		}
929		// 中止：收回集合必须恰为中止时仍由原批次配送的待配送成员（无有效回执且未在
930		// 此前各次续接中转交，按原成员顺序），且每件收回包裹的轨迹中都有与该中止
931		// 请求一致的收回记录；中止记录与收回轨迹不一致即损坏。
932		for req, a := range l.Aborts {
933			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
934				len(a.Parcels) == 0 || a.Time.IsZero() {
935				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
936			}
937			b, ok := l.Batches[a.Batch]
938			if !ok || b == nil {
939				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
940			}
941			if b.AbortedBy != req {
942				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
943			}
944			if b.TransferredBy != "" {
945				return fmt.Errorf("%w: 批次 %q 不能同时标记中止与永久转交", ErrCorrupt, a.Batch)
946			}
947			if a.Station != b.Station {
948				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
949			}
950			expect := b.openParcels(l)
951			if len(expect) != len(a.Parcels) {
952				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
953			}
954			for i := range expect {
955				if expect[i] != a.Parcels[i] {
956					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
957				}
958			}
959			for _, pid := range a.Parcels {
960				p, ok := l.Parcels[pid]
961				if !ok {
962					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
963				}
964				found := false
965				for _, e := range p.Trail {
966					if e.Op == "收回" && e.Request == req {
967						found = true
968						break
969					}
970				}
971				if !found {
972					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
973				}
974			}
975		}
976		// 续接：每次续接必须由原批次按提交顺序的续接列表引用，新批次必须由该续接创建且
977		// 成员、站点、配送员、接手时间与之一致；本次转交集合必须非空、不重复、按原成员
978		// 顺序排列，且每件都属原批次、在该次续接之前未转交也无有效回执（同件从同批次
979		// 只能转交一次，已转交件不能回执原批次）；每件转交包裹的轨迹中都有与该续接
980		// 请求一致的续接记录。分批续接只转走部分待配送件，集合不必等于当时全部余件；
981		// 原批次永久转交（TransferredBy 置位）时必须已无待配送件。关联缺失或矛盾即损坏。
982		for req, t := range l.Transfers {
