1351			if f.ReleasedBy == "" && p.Station != f.Station {
1352				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
1353					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
1354			}
1355			if f.ReleasedBy != "" {
1356				u, ok := l.Unfreezes[f.ReleasedBy]
1357				if !ok || u == nil || u.Incident != no || u.Parcel != f.Parcel {
1358					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
1359				}
1360			}
1361		}
1362		activeByParcel := make(map[string]string)
1363		for req, u := range l.Unfreezes {
1364			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
1365				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
1366			}
1367			f, ok := l.Freezes[u.Incident]
1368			if !ok || f == nil {
1369				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
1370			}
1371			if f.Parcel != u.Parcel {
1372				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
1373			}
1374			if f.ReleasedBy != req {
1375				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
1376			}
1377		}
1378		for no, f := range l.Freezes {
1379			if f.ReleasedBy != "" {
1380				continue
1381			}
1382			if other, dup := activeByParcel[f.Parcel]; dup {
1383				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
1384			}
1385			activeByParcel[f.Parcel] = no
1386			if openIncident[f.Parcel] != no {
1387				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
1388					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
1389			}
1390			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
1391				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
1392			}
1393		}
1394		return nil
1395	}
1396	
1397	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
1398	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
1399	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
1400	func coordinationPath(path string) (string, error) {
1401		abs, err := filepath.Abs(path)
1402		if err != nil {
1403			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
1404		}
1405		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
1406			abs = resolved
1407		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
1408			abs = filepath.Join(dir, filepath.Base(abs))
1409		}
1410		return abs + ".lock", nil
1411	}
1412	
1413	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
1414	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
1415	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
1416	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
1417	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
1418	// 无需人工删除协调文件即可继续作业。
1419	func OpenForUpdate(path string) (s *Store, release func(), err error) {
1420		lockPath, err := coordinationPath(path)
1421		if err != nil {
1422			return nil, nil, err
1423		}
1424		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
1425			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
1426		}
1427		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
1428		if err != nil {
1429			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
1430		}
1431		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
1432			_ = lock.Close()
1433			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
1434		}
1435		release = func() {
1436			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
1437			_ = lock.Close()
1438		}
1439		s, err = Open(path)
1440		if err != nil {
1441			release()
1442			return nil, nil, err
1443		}
1444		return s, release, nil
1445	}
1446	
1447	// Register 执行单件收件登记并将结果整体落盘。
1448	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
1449		if _, ok := s.data.Parcels[id]; ok {
1450			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
1451		}
1452		p := &Parcel{
1453			ID:         id,
1454			Station:    station,
1455			Status:     statusInStation,
1456			Registered: now,
1457			Trail: []Event{{
1458				Op:      "收件",
1459				Station: station,
1460				Time:    now,
1461			}},
1462		}
1463		s.data.Parcels[id] = p
1464		if err := s.save(); err != nil {
1465			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
1466			return nil, err
1467		}
1468		return p, nil
1469	}
1470	
1471	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
1472	func (s *Store) Query(id string) (*Parcel, error) {
1473		p, ok := s.data.Parcels[id]
1474		if !ok {
1475			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
1476		}
1477		return p, nil
1478	}
1479	
1480	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
1481	func (s *Store) ActiveFreeze(id string) *FreezeResult {
1482		p, ok := s.data.Parcels[id]
1483		if !ok {
1484			return nil
1485		}
1486		if no := activeFreeze(p); no != "" {
1487			return s.data.Freezes[no]
1488		}
1489		return nil
1490	}
1491	
1492	// Handoff 提交一次多件包裹的站点交接。
1493	//
1494	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1495	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1496	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1497	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1498	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1499		if saved, ok := s.data.Handoffs[request]; ok {
1500			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1501				return saved, true, nil
1502			}
1503			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1504		}
1505	
1506		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1507		for _, id := range parcels {
1508			p, ok := s.data.Parcels[id]
1509			if !ok {
1510				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1511			}
1512			if p.Station != from {
1513				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1514			}
1515			if inc := activeFreeze(p); inc != "" {
1516				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1517			}
1518			if p.Status != statusInStation {
1519				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1520			}
1521		}
1522	
1523		res := &HandoffResult{
1524			Request: request,
1525			From:    from,
1526			To:      to,
1527			Parcels: append([]string(nil), parcels...),
1528			Time:    now,
1529		}
1530		s.data.Handoffs[request] = res
1531	
1532		// 记录旧值，落盘失败时整体回滚。
1533		prev := make(map[string]struct {
1534			station string
1535			trail   []Event
1536		}, len(parcels))
1537		for _, id := range parcels {
1538			p := s.data.Parcels[id]
1539			prev[id] = struct {
1540				station string
1541				trail   []Event
1542			}{p.Station, append([]Event(nil), p.Trail...)}
1543			p.Station = to
1544			p.Status = statusInStation
1545			p.Trail = append(p.Trail, Event{
1546				Op:      "交接",
1547				Station: to,
1548				Request: request,
1549				Time:    now,
1550			})
1551		}
1552	
1553		if err := s.save(); err != nil {
1554			delete(s.data.Handoffs, request)
1555			for id, old := range prev {
1556				p := s.data.Parcels[id]
1557				p.Station = old.station
1558				p.Trail = old.trail
1559			}
1560			return nil, false, err
1561		}
1562		return res, false, nil
1563	}
1564	
1565	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1566	//
1567	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1568	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1569	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1570	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1571	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1572	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1573	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1574	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1575		if saved, ok := s.data.Returns[request]; ok {
1576			if saved.Handoff == handoffReq && saved.Reason == reason {
1577				return saved, true, nil
1578			}
1579			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1580				request, saved.Handoff, saved.Reason)
1581		}
1582	
1583		h, ok := s.data.Handoffs[handoffReq]
1584		if !ok {
1585			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1586		}
1587		if h.ReturnedBy != "" {
1588			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1589		}
1590	
1591		// 先做全部校验，任何一件不满足都整批拒绝。
1592		for _, id := range h.Parcels {
1593			p, ok := s.data.Parcels[id]
1594			if !ok {
1595				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1596			}
1597			if inc := activeFreeze(p); inc != "" {
1598				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1599			}
1600			if p.Station != h.To || p.Status != statusInStation {
1601				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1602					id, p.Station, p.Status, h.To)
1603			}
1604			last := lastFlowEvent(p.Trail)
1605			if last.Op != "交接" || last.Request != handoffReq {
1606				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1607					id, handoffReq)
1608			}
1609		}
1610	
1611		res := &ReturnResult{
1612			Request: request,
1613			Handoff: handoffReq,
1614			From:    h.To,
1615			To:      h.From,
1616			Reason:  reason,
1617			Parcels: append([]string(nil), h.Parcels...),
1618			Time:    now,
1619		}
1620		s.data.Returns[request] = res
1621		h.ReturnedBy = request
1622	
1623		// 记录旧值，落盘失败时整体回滚。
1624		prev := make(map[string]struct {
1625			station string
1626			trail   []Event
1627		}, len(h.Parcels))
1628		for _, id := range h.Parcels {
1629			p := s.data.Parcels[id]
1630			prev[id] = struct {
1631				station string
1632				trail   []Event
1633			}{p.Station, append([]Event(nil), p.Trail...)}
1634			p.Station = h.From
1635			p.Status = statusInStation
1636			p.Trail = append(p.Trail, Event{
1637				Op:         "退回",
1638				Station:    h.From,
1639				From:       h.To,
1640				Request:    request,
1641				RefRequest: handoffReq,
1642				Reason:     reason,
1643				Time:       now,
1644			})
1645		}
1646	
1647		if err := s.save(); err != nil {
1648			delete(s.data.Returns, request)
1649			h.ReturnedBy = ""
1650			for id, old := range prev {
1651				p := s.data.Parcels[id]
1652				p.Station = old.station
1653				p.Trail = old.trail
1654			}
1655			return nil, false, err
1656		}
1657		return res, false, nil
1658	}
1659	
1660	// Dispatch 提交一次配送批次出站。
1661	//
1662	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1663	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1664	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1665	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1666	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1667	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1668		if saved, ok := s.data.Batches[batch]; ok {
1669			if saved.RelayedFrom != "" {
1670				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1671					batch, saved.RelayRequest, saved.RelayedFrom)
1672			}
1673			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1674				return saved, true, nil
1675			}
1676			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1677		}
1678	
1679		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1680		for _, id := range parcels {
1681			p, ok := s.data.Parcels[id]
1682			if !ok {
1683				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1684			}
1685			if p.Station != station {
1686				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1687			}
1688			if inc := activeFreeze(p); inc != "" {
1689				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1690			}
1691			if p.Status != statusInStation {
1692				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1693			}
1694		}
1695	
1696		res := &BatchResult{
1697			Batch:    batch,

