1766	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1767		if saved, ok := s.data.Receipts[request]; ok {
1768			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1769				return saved, true, nil, nil
1770			}
1771			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1772				request, saved.Batch, saved.Parcel, saved.Result)
1773		}
1774	
1775		b, ok := s.data.Batches[batch]
1776		if !ok {
1777			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1778		}
1779		member := false
1780		for _, id := range b.Parcels {
1781			if id == parcel {
1782				member = true
1783				break
1784			}
1785		}
1786		if !member {
1787			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1788		}
1789		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1790			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1791		}
1792		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1793		if p.Status != statusDelivering || currentBatch(p) != batch {
