1795		}
1796	
1797		res = &ReceiptResult{
1798			Request: request,
1799			Batch:   batch,
1800			Parcel:  parcel,
1801			Result:  result,
1802			Reason:  reason,
1803			Time:    now,
1804		}
1805		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1806	
1807		// 记录旧值，undo 在整体落盘失败时回滚。
1808		oldStatus, oldStation := p.Status, p.Station
1809		oldTrailLen := len(p.Trail)
1810		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1811	
1812		if result == resultSigned {
