1814		} else {
1815			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1816			p.Station = b.Station
1817		}
1818		p.Trail = append(p.Trail, Event{
1819			Op:      "回执",
1820			Station: p.Station,
1821			Batch:   batch,
1822			Result:  result,
1823			Reason:  reason,
1824			Request: request,
1825			Time:    now,
1826		})
1827		b.Receipts[parcel] = entry
1828		s.data.Receipts[request] = res
1829	
1830		undo = func() {
1831			delete(s.data.Receipts, request)
1832			if hadEntry {
