1843	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
1844	type ReceiptImportRecord struct {
1845		Request string // 回执请求号（与逐件 receipt 共用去重范围）
1846		Batch   string // 配送批次号
1847		Parcel  string // 包裹编号
1848		Result  string // 签收 | 失败
1849		Reason  string // 失败原因（失败时非空，签收时为空）
1850	}
