1852	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
1853	type ReceiptImportItem struct {
1854		Record   ReceiptImportRecord // 清洗后的记录内容
1855		Time     time.Time           // 发生时间（重放时为首次保存的时间）
1856		Replayed bool                // true 表示同内容历史重放，未产生新变更
1857		Revoked  bool                // true 表示该回执已被撤销（仅历史重放可能；重放不恢复回执）
1858	}
