1860	// ImportReceipts 按文件顺序整批应用回执记录。
1861	//
1862	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1863	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1864	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1865	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1866	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1867	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1868	// 全部为历史重放时不改写台账。
1869	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1870		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1871		work, err := s.fork()
1872		if err != nil {
1873			return nil, err
1874		}
1875		items := make([]ReceiptImportItem, 0, len(records))
1876		hasNew := false
1877		for i, rec := range records {
1878			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1879			if err != nil {
1880				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1881			}
1882			if !replayed {
1883				hasNew = true
1884			}
1885			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
1886		}
1887		if !hasNew {
1888			return items, nil // 全部为历史重放：不改写台账
1889		}
1890	
1891		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1892		orig := s.data
1893		s.data = work.data
1894		if err := s.save(); err != nil {
1895			s.data = orig
1896			return nil, err
1897		}
1898		return items, nil
1899	}
