2036	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
2037	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
2038	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
2039	// 冻结只是管理记录，不移动实物、不算新流转。
2040	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
2041	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
2042	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
2043	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
2044	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
2045		if saved, ok := s.data.Freezes[incident]; ok {
2046			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
2047				return saved, true, nil
2048			}
2049			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
2050				incident, saved.Parcel, saved.Station, saved.Reason)
2051		}
2052	
2053		p, ok := s.data.Parcels[parcel]
2054		if !ok {
2055			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
2056		}
2057		if p.Station != station {
2058			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
2059		}
2060		if p.Status != statusInStation {
2061			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
2062		}
2063	
2064		res = &FreezeResult{
2065			Incident: incident,
2066			Parcel:   parcel,
2067			Station:  station,
2068			Reason:   reason,
2069			Time:     now,
2070		}
2071		s.data.Freezes[incident] = res
2072	
2073		// 记录旧值，落盘失败时整体回滚。
2074		oldStatus := p.Status
2075		oldTrail := append([]Event(nil), p.Trail...)
2076		p.Status = statusFrozen // 站点不变
2077		p.Trail = append(p.Trail, Event{
2078			Op:       "冻结",
2079			Station:  station,
2080			Incident: incident,
2081			Reason:   reason,
2082			Time:     now,
2083		})
2084	
2085		if err := s.save(); err != nil {
2086			delete(s.data.Freezes, incident)
2087			p.Status, p.Trail = oldStatus, oldTrail
2088			return nil, false, err
2089		}
2090		return res, false, nil
