2093	// Unfreeze 解除一件包裹当前的异常冻结。
2094	//
2095	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
2096	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
2097	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
2098	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
2099	// 解除只是管理记录，不移动实物、不算新流转。
2100	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
2101	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
2102	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
2103	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
2104		if saved, ok := s.data.Unfreezes[request]; ok {
2105			if saved.Incident == incident && saved.Note == note {
2106				return saved, true, nil
2107			}
2108			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
2109				request, saved.Incident, saved.Note)
2110		}
2111	
2112		f, ok := s.data.Freezes[incident]
2113		if !ok {
2114			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
2115		}
2116		if f.ReleasedBy != "" {
2117			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
2118		}
2119		p, ok := s.data.Parcels[f.Parcel]
2120		if !ok {
2121			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
2122		}
2123		if p.Status != statusFrozen || activeFreeze(p) != incident {
2124			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
2125				incident, f.Parcel, activeFreeze(p))
2126		}
2127	
2128		res = &UnfreezeResult{
2129			Request:  request,
2130			Incident: incident,
2131			Parcel:   f.Parcel,
2132			Note:     note,
2133			Time:     now,
2134		}
2135		s.data.Unfreezes[request] = res
2136		f.ReleasedBy = request
2137	
2138		// 记录旧值，落盘失败时整体回滚。
2139		oldStatus := p.Status
2140		oldTrail := append([]Event(nil), p.Trail...)
2141		p.Status = statusInStation // 在原站恢复在站，站点不变
2142		p.Trail = append(p.Trail, Event{
2143			Op:       "解除冻结",
2144			Station:  f.Station,
2145			Incident: incident,
2146			Request:  request,
2147			Note:     note,
2148			Time:     now,
2149		})
2150	
2151		if err := s.save(); err != nil {
2152			delete(s.data.Unfreezes, request)
2153			f.ReleasedBy = ""
2154			p.Status, p.Trail = oldStatus, oldTrail
2155			return nil, false, err
2156		}
2157		return res, false, nil
2158	}
