2160	// Abort 中止一个配送批次：配送员已将该批次仍由本批次配送的全部待配送包裹实物
2161	// 收回出发站。成员与站点取自原批次结果，不允许另选成员或站点。
2162	//
2163	// 首次中止：批次必须存在、未中止、未永久转交，且至少有一件待配送成员（无有效
2164	// 回执且未在此前各次续接中转交）；这些成员必须仍在原批次配送中、归属出发站，
2165	// 任一不符整批拒绝、不作任何改动。已回执成员与已转交成员不检查也不变更，其后续
2166	// 流转或冻结不阻止中止。全部满足时按原成员顺序将全部待配送件恢复“在站”
2167	// （站点为出发站），各追加一条含批次、中止请求号、原因、站点和时间的收回记录；
2168	// 收回不是失败回执，批次回执记录与转交记录不变。中止永久关闭原批次，原成员顺序、
2169	// 配送员与出站时间保留不变。
2170	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
2171	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
2172	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
2173	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
2174	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
2175	// 每批只能成功中止一次：换请求号再中止、中止已完成或已永久转交的批次均拒绝；
2176	// 失败的首次中止不占用请求号。
2177	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
2178		if saved, ok := s.data.Aborts[request]; ok {
2179			if saved.Batch == batch && saved.Reason == reason {
2180				return saved, true, nil
2181			}
2182			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
2183				request, saved.Batch, saved.Reason)
2184		}
2185	
2186		b, ok := s.data.Batches[batch]
2187		if !ok {
2188			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
2189		}
2190		if b.AbortedBy != "" {
2191			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
2192		}
2193		if b.TransferredBy != "" {
2194			return nil, false, fmt.Errorf("中止失败：批次 %q 已永久转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
2195		}
2196	
2197		// 按原成员顺序挑出仍由本批次配送的待配送成员（无有效回执且未转交）。
2198		recalled := b.openParcels(&s.data)
2199		if len(recalled) == 0 {
2200			return nil, false, fmt.Errorf("中止失败：批次 %q 没有待配送成员，不能中止", batch)
2201		}
2202	
2203		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2204		for _, pid := range recalled {
2205			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2206			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
2207				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
2208					pid, p.Station, p.Status, batch, b.Station)
2209			}
2210		}
2211	
2212		res = &AbortResult{
2213			Request: request,
2214			Batch:   batch,
2215			Station: b.Station,
2216			Reason:  reason,
2217			Parcels: recalled,
2218			Time:    now,
2219		}
2220		s.data.Aborts[request] = res
2221		b.AbortedBy = request
2222	
2223		// 记录旧值，落盘失败时整体回滚。
2224		prev := make(map[string]struct {
2225			status string
2226			trail  []Event
2227		}, len(recalled))
2228		for _, pid := range recalled {
2229			p := s.data.Parcels[pid]
2230			prev[pid] = struct {
2231				status string
2232				trail  []Event
2233			}{p.Status, append([]Event(nil), p.Trail...)}
2234			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
2235			p.Trail = append(p.Trail, Event{
2236				Op:      "收回",
2237				Station: b.Station,
2238				Batch:   batch,
2239				Request: request,
2240				Reason:  reason,
2241				Time:    now,
2242			})
2243		}
2244	
2245		if err := s.save(); err != nil {
2246			delete(s.data.Aborts, request)
2247			b.AbortedBy = ""
2248			for pid, old := range prev {
2249				p := s.data.Parcels[pid]
2250				p.Status = old.status
2251				p.Trail = old.trail
2252			}
2253			return nil, false, err
2254		}
2255		return res, false, nil
2256	}
