2258	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
2259	func (s *Store) BatchAbort(batch string) *AbortResult {
2260		b, ok := s.data.Batches[batch]
2261		if !ok || b.AbortedBy == "" {
2262			return nil
2263		}
2264		return s.data.Aborts[b.AbortedBy]
