2267	// Transfer 在配送途中把原批次的部分或全部待配送包裹交给另一配送员，新建批次
2268	// 继续配送，无需回站。站点取自原批次，不可另选；成员可两种方式选择：parcels
2269	// 为 nil 表示不选成员，取当时全部无有效回执且未转交的待配送件；非 nil 为显式
2270	// 选择的非空、不重复集合（由调用方清洗）。
2271	//
2272	// 首次续接：原批次必须存在、未中止、未永久转交；新批次号必须从未被出站或续接
2273	// 使用；新配送员必须与原配送员不同。显式集合的每件选中件都必须属于原批次、
2274	// 无有效回执且未转交，并仍在该批次由出发站配送中；不选成员时本次集合为当时全部
2275	// 待配送件（它们同样必须仍在原批次配送中）。任一不符整次拒绝、不作任何改动。
2276	// 已有有效回执或已转交的成员不检查也不变更，其后续流转或冻结不阻止续接。
2277	// 成功时按原成员顺序以选中件创建新批次，沿用出发站，记录新配送员及接手时间；
2278	// 选中件保持“配送中”及原站点，当前配送归属切换到新批次，各追加一条含请求号、
2279	// 前后批次、新配送员、站点、原因和时间的续接记录；未选余件不变。原成员、配送员、
2280	// 出站时间与已有回执保留。原批次可多次分批续接：仍有待配送件时保持配送中；
2281	// 余件经回执办结时已完成（可按原条件撤销恢复配送）；续接转走最后一件待配送件时
2282	// 原批次才永久关闭为“已转交”。转交不算回执、收回或再次出站。续接算新的流转，
2283	// 续接后不能退回配送前的旧交接。
2284	// 两种选择方式共用续接请求号去重范围，可与批次号、包裹号及其他业务编号同名：
2285	// 相同请求号且原批次、新批次、新配送员、清理后的原因、选择方式相同（显式集合
2286	// 换序无关），直接返回首次转交集合、续接信息及时间，replayed 为 true，不检查
2287	// 现状、不重算余件、不追加轨迹、不改写台账（后续回执、中止或再次续接后仍成立）；
2288	// 请求号相同但内容或选择方式不同报冲突；失败的首次续接不占用请求号。
2289	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, parcels []string, now time.Time) (res *TransferResult, replayed bool, err error) {
2290		explicit := parcels != nil
2291		if saved, ok := s.data.Transfers[request]; ok {
2292			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier &&
2293				saved.Reason == reason && saved.Explicit == explicit &&
2294				(!explicit || sameSet(saved.Parcels, parcels)) {
2295				return saved, true, nil
2296			}
2297			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
2298				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
2299		}
2300	
2301		b, ok := s.data.Batches[fromBatch]
2302		if !ok {
2303			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
2304		}
2305		if b.AbortedBy != "" {
2306			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
2307		}
2308		if b.TransferredBy != "" {
2309			return nil, false, fmt.Errorf("续接失败：批次 %q 已永久转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
2310		}
2311		if _, used := s.data.Batches[toBatch]; used {
2312			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
2313		}
2314		if courier == b.Courier {
2315			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
2316		}
2317	
2318		// 本次集合：显式方式校验指定集合，不选方式取当时全部待配送件；均按原成员顺序。
2319		open := b.openParcels(&s.data)
2320		openSet := make(map[string]bool, len(open))
2321		for _, pid := range open {
2322			openSet[pid] = true
2323		}
2324		var moved []string
2325		if explicit {
2326			if len(parcels) == 0 {
2327				return nil, false, fmt.Errorf("续接失败：显式选择的包裹集合不可为空，整次续接未执行")
2328			}
2329			want := make(map[string]bool, len(parcels))
2330			for _, pid := range parcels {
2331				if want[pid] {
2332					return nil, false, fmt.Errorf("续接失败：显式集合中包裹 %q 重复，整次续接未执行", pid)
2333				}
2334				want[pid] = true
2335				if !openSet[pid] {
2336					// 区分不属于批次、已有有效回执/已转交等情形，给出明确原因。
2337					member := false
2338					for _, mid := range b.Parcels {
2339						if mid == pid {
2340							member = true
2341							break
2342						}
2343					}
2344					if !member {
2345						return nil, false, fmt.Errorf("续接失败：包裹 %q 不属于原批次 %q，整次续接未执行", pid, fromBatch)
2346					}
2347					return nil, false, fmt.Errorf("续接失败：包裹 %q 在批次 %q 已有有效回执或已转交，不能再次选中，整次续接未执行", pid, fromBatch)
2348				}
2349			}
2350			for _, pid := range b.Parcels {
2351				if want[pid] {
2352					moved = append(moved, pid)
2353				}
2354			}
2355		} else {
2356			moved = append(moved, open...)
2357			if len(moved) == 0 {
2358				return nil, false, fmt.Errorf("续接失败：批次 %q 没有待配送成员，不能续接", fromBatch)
2359			}
2360		}
2361	
2362		// 先做全部校验：选中件必须仍在原批次由出发站配送中，任一不符整次拒绝。
2363		for _, pid := range moved {
2364			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2365			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
2366				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整次续接未执行",
2367					pid, p.Station, p.Status, fromBatch, b.Station)
2368			}
2369		}
2370	
2371		res = &TransferResult{
2372			Request:     request,
2373			FromBatch:   fromBatch,
2374			ToBatch:     toBatch,
2375			Station:     b.Station,
2376			FromCourier: b.Courier,
2377			ToCourier:   courier,
2378			Reason:      reason,
2379			Parcels:     append([]string(nil), moved...),
2380			Time:        now,
2381			Explicit:    explicit,
2382		}
2383		s.data.Transfers[request] = res
2384		s.data.Batches[toBatch] = &BatchResult{
2385			Batch:        toBatch,
2386			Station:      b.Station,
2387			Courier:      courier,
2388			Parcels:      append([]string(nil), moved...),
2389			Time:         now,
2390			Receipts:     map[string]*ReceiptEntry{},
2391			RelayedFrom:  fromBatch,
2392			RelayRequest: request,
2393		}
2394		b.Transfers = append(b.Transfers, request)
2395		// 转走最后一件待配送件：原批次永久关闭为“已转交”；有余件则保持配送中。
2396		if len(b.openParcels(&s.data)) == 0 {
2397			b.TransferredBy = request
2398		}
2399	
2400		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
2401		prev := make(map[string][]Event, len(moved))
2402		for _, pid := range moved {
2403			p := s.data.Parcels[pid]
2404			prev[pid] = append([]Event(nil), p.Trail...)
2405			p.Trail = append(p.Trail, Event{
2406				Op:        "续接",
2407				Station:   b.Station,
2408				Batch:     toBatch,
2409				FromBatch: fromBatch,
2410				Courier:   courier,
2411				Request:   request,
2412				Reason:    reason,
2413				Time:      now,
2414			})
2415		}
2416	
2417		if err := s.save(); err != nil {
2418			delete(s.data.Transfers, request)
2419			delete(s.data.Batches, toBatch)
2420			b.Transfers = b.Transfers[:len(b.Transfers)-1]
2421			b.TransferredBy = ""
2422			for pid, old := range prev {
2423				s.data.Parcels[pid].Trail = old
2424			}
2425			return nil, false, err
2426		}
2427		return res, false, nil
2428	}
