2430	// BatchTransferSource 返回永久关闭该批次为“已转交”的最后一次续接结果；
2431	// 批次不存在或仍开放（尚未永久转交）时返回 nil。
2432	func (s *Store) BatchTransferSource(batch string) *TransferResult {
2433		b, ok := s.data.Batches[batch]
2434		if !ok || b.TransferredBy == "" {
2435			return nil
2436		}
2437		return s.data.Transfers[b.TransferredBy]
2438	}
2439	
2440	// BatchTransfers 按提交顺序返回以该批次为原批次的各次续接结果；
2441	// 批次不存在或从未续接时为空。分批续接时可能含多条，最后一条未必永久关闭原批次。
2442	func (s *Store) BatchTransfers(batch string) []*TransferResult {
2443		b, ok := s.data.Batches[batch]
2444		if !ok {
2445			return nil
2446		}
2447		out := make([]*TransferResult, 0, len(b.Transfers))
2448		for _, req := range b.Transfers {
2449			if t := s.data.Transfers[req]; t != nil {
2450				out = append(out, t)
2451			}
2452		}
2453		return out
2454	}
2455	
2456	// transferOfParcel 返回某成员在指定批次下被转交的续接结果；该件未从该批次转交时为 nil。
2457	func (s *Store) transferOfParcel(batch, pid string) *TransferResult {
2458		b, ok := s.data.Batches[batch]
2459		if !ok {
2460			return nil
2461		}
2462		for _, req := range b.Transfers {
2463			t := s.data.Transfers[req]
2464			if t == nil {
2465				continue
2466			}
2467			for _, id := range t.Parcels {
2468				if id == pid {
2469					return t
2470				}
2471			}
2472		}
2473		return nil
2474	}
2475	
2476	// TransferOf 按续接请求号返回续接结果；不存在时返回 nil。
2477	func (s *Store) TransferOf(request string) *TransferResult {
2478		return s.data.Transfers[request]
2479	}
