2481	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2482	//
2483	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2484	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2485	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2486	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2487	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2488	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2489	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2490	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2491	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2492		if saved, ok := s.data.Shipments[shipment]; ok {
2493			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2494				return saved, true, nil
2495			}
2496			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2497		}
2498	
2499		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2500		for _, id := range parcels {
2501			p, ok := s.data.Parcels[id]
2502			if !ok {
2503				return nil, false, fmt.Errorf("发运失败：包裹 %q 未登记，整单发运未执行", id)
2504			}
2505			if p.Station != from {
2506				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前归属 %q，不在源站 %q，整单发运未执行", id, p.Station, from)
2507			}
2508			if p.Status != statusInStation {
2509				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前状态为 %q，不是在站，整单发运未执行", id, p.Status)
2510			}
2511		}
2512	
2513		res = &ShipmentResult{
2514			Shipment: shipment,
2515			From:     from,
2516			To:       to,
2517			Parcels:  append([]string(nil), parcels...),
2518			Time:     now,
2519		}
2520		s.data.Shipments[shipment] = res
2521	
2522		// 记录旧值，落盘失败时整体回滚。
2523		prev := make(map[string]struct {
2524			status string
2525			trail  []Event
2526		}, len(parcels))
2527		for _, id := range parcels {
2528			p := s.data.Parcels[id]
2529			prev[id] = struct {
2530				status string
2531				trail  []Event
2532			}{p.Status, append([]Event(nil), p.Trail...)}
2533			p.Status = statusInTransit // 归属站点暂记源站，整单转为站间在途
2534			p.Trail = append(p.Trail, Event{
2535				Op:       "发运",
2536				Station:  from,
2537				From:     from,
2538				To:       to,
2539				Shipment: shipment,
2540				Time:     now,
2541			})
2542		}
2543	
2544		if err := s.save(); err != nil {
2545			delete(s.data.Shipments, shipment)
2546			for id, old := range prev {
2547				p := s.data.Parcels[id]
2548				p.Status = old.status
2549				p.Trail = old.trail
2550			}
2551			return nil, false, err
2552		}
2553		return res, false, nil
2554	}
