2556	// Receive 提交一次到站接收：运输单的部分或全部未到成员到达当前有效目的站。
2557	// parcels 为 nil 表示不选成员，接收当时全部尚未接收件；非 nil 为显式选择的
2558	// 非空、不重复集合（由调用方清洗）。
2559	//
2560	// 首次接收：运输单必须存在，接收站点必须等于运输单当前有效目的站（原目的站
2561	// 应用已有各次改址后），本次至少接收一件。显式集合的每件选中件都必须属于原单、
2562	// 尚未接收，且仍在源站归该单在途；不选成员时本次集合为当时的全部尚未接收件。
2563	// 任一不满足则整次拒绝，不作任何改动。
2564	// 已收件不再检查接收条件也不变更，其后续交接、冻结、配送或再次发运不妨碍余件接收。
2565	// 成功时按发运保存顺序将本次成员改归有效目的站、恢复“在站”，各追加一条含运输单号、
2566	// 两站、接收请求号和时间的接收记录；全部成员到齐后运输单永久标记为已接收，
2567	// 随后可继续在站作业。接收算新的流转：接收后不能退回此前的旧交接。
2568	// 两种选择方式共用接收请求号去重范围，与运输单号及已有各类编号独立，允许同名：
2569	// 相同接收请求号且运输单、接收站点、选择方式相同（显式集合换序无关），直接返回
2570	// 首次接收集合与时间，replayed 为 true，不检查现状、不重算余件、不追加轨迹、
2571	// 不改写台账（全部接收及后续流转后仍成立）；请求号相同但运输单、接收站点、
2572	// 选择方式或显式集合不同报冲突；全部接收后新请求拒绝；失败的首次接收不占用请求号。
2573	func (s *Store) Receive(request, shipment, station string, parcels []string, now time.Time) (res *ReceiveResult, replayed bool, err error) {
2574		explicit := parcels != nil
2575		if saved, ok := s.data.Receives[request]; ok {
2576			if saved.Shipment == shipment && saved.Station == station && saved.Explicit == explicit &&
2577				(!explicit || sameSet(saved.Parcels, parcels)) {
2578				return saved, true, nil
2579			}
2580			return nil, false, fmt.Errorf("接收请求号 %q 已用于一次不同的接收（运输单=%q 接收站点=%q），内容冲突",
2581				request, saved.Shipment, saved.Station)
2582		}
2583	
2584		sh, ok := s.data.Shipments[shipment]
2585		if !ok {
2586			return nil, false, fmt.Errorf("接收失败：运输单号 %q 不存在", shipment)
2587		}
2588		eff := s.effectiveTo(sh)
2589		if station != eff {
2590			return nil, false, fmt.Errorf("接收失败：接收站点 %q 不是运输单 %q 的当前有效目的站 %q，本次接收未执行", station, shipment, eff)
2591		}
2592	
2593		received := s.receivedUnder(shipment)
2594		var members []string // 本次接收集合，按发运保存顺序
2595		if explicit {
2596			if len(parcels) == 0 {
2597				return nil, false, fmt.Errorf("接收失败：显式选择的包裹集合不可为空，本次接收未执行")
2598			}
2599			want := make(map[string]bool, len(parcels))
2600			for _, pid := range parcels {
2601				want[pid] = true
2602			}
2603			// 先做全部校验：选中件均属原单、尚未接收且仍归该单在途，任一不符整次拒绝。
2604			for _, pid := range parcels {
2605				member := false
2606				for _, mid := range sh.Parcels {
2607					if mid == pid {
2608						member = true
2609						break
2610					}
2611				}
2612				if !member {
2613					return nil, false, fmt.Errorf("接收失败：包裹 %q 不属于运输单 %q，本次接收未执行", pid, shipment)
2614				}
2615				if received[pid] {
2616					return nil, false, fmt.Errorf("接收失败：包裹 %q 已在运输单 %q 下接收，不能重复接收，本次接收未执行", pid, shipment)
2617				}
2618				p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2619				if p.Status != statusInTransit || p.Station != sh.From {
2620					return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，本次接收未执行",
2621						pid, p.Station, p.Status, shipment, sh.From)
2622				}
2623			}
2624			for _, mid := range sh.Parcels {
2625				if want[mid] {
2626					members = append(members, mid)
2627				}
2628			}
2629		} else {
2630			// 不选成员：本次集合为当时的全部尚未接收件，按发运保存顺序。
2631			for _, mid := range sh.Parcels {
2632				if !received[mid] {
2633					members = append(members, mid)
2634				}
2635			}
2636			if len(members) == 0 {
2637				return nil, false, fmt.Errorf("接收失败：运输单 %q 已全部接收（接收请求号 %q），没有尚未接收的成员，不能再次接收",
2638					shipment, sh.ReceivedBy)
2639			}
2640		}
2641	
2642		res = &ReceiveResult{
2643			Request:  request,
2644			Shipment: shipment,
2645			Station:  station,
2646			Parcels:  members,
2647			Time:     now,
2648			Explicit: explicit,
2649		}
2650		s.data.Receives[request] = res
2651		oldReceivedBy := sh.ReceivedBy
2652		if len(received)+len(members) == len(sh.Parcels) {
2653			sh.ReceivedBy = request // 全部成员到齐：运输单永久标记为已接收
2654		}
2655	
2656		// 记录旧值，落盘失败时整体回滚。
2657		prev := make(map[string]struct {
2658			station string
2659			status  string
2660			trail   []Event
2661		}, len(members))
2662		for _, pid := range members {
2663			p := s.data.Parcels[pid]
2664			prev[pid] = struct {
2665				station string
2666				status  string
2667				trail   []Event
2668			}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
2669			p.Station = eff
2670			p.Status = statusInStation
2671			p.Trail = append(p.Trail, Event{
2672				Op:       "接收",
2673				Station:  eff,
2674				From:     sh.From,
2675				To:       eff,
2676				Shipment: shipment,
2677				Request:  request,
