2695	// Reroute 提交一次运输途中改址：将一张运输单当前全部未收件改送另一目的站，
2696	// 不另建运输单、不重新发运。成员取自受理时的全部未收件，不允许另选。
2697	//
2698	// 首次受理：运输单必须存在且仍有未收件；预期当前目的站必须等于当前有效目的站
2699	// （原目的站应用已有各次改址后）；新目的站必须不同于当前有效目的站和源站。
2700	// 本次集合为受理时的全部未收件，每件都必须仍归该单在源站站间在途，任一不符
2701	// 整次拒绝、不作任何改动。已收件不参与受理条件检查也不变更，其后续合法作业
2702	// 不阻止改址。成功时按原发运顺序保存本次集合，成员仍归源站、保持站间在途及
2703	// 作业限制，只变更余件的有效目的站，逐件追加一条含请求号、运输单、前后目的站、
2704	// 原因和时间的改址轨迹；原成员、发运结果、已有接收事实与轨迹永久保留。
2705	// 改址可发生在发运与接收之间，允许再次改址（每次以当时余件为准），全部接收后
2706	// 拒绝新改址；改址不算到站、不恢复旧交接退回资格。
2707	// 改址请求号独立去重，可与运输单号及其他业务编号同名：相同请求号且运输单、
2708	// 预期当前目的站、新目的站、清理后的原因相同，直接返回首次改址信息、集合与
2709	// 时间，replayed 为 true，不检查现状、不重算余件、不改写台账（再次改址、接收
2710	// 和后续流转后仍成立）；请求号相同但内容不同报冲突；失败的首次改址不占用请求号。
2711	func (s *Store) Reroute(request, shipment, expect, to, reason string, now time.Time) (res *RerouteResult, replayed bool, err error) {
2712		if saved, ok := s.data.Reroutes[request]; ok {
2713			if saved.Shipment == shipment && saved.From == expect && saved.To == to && saved.Reason == reason {
2714				return saved, true, nil
2715			}
2716			return nil, false, fmt.Errorf("改址请求号 %q 已用于一次不同的改址（运输单=%q 新目的站=%q），内容冲突",
2717				request, saved.Shipment, saved.To)
2718		}
2719	
2720		sh, ok := s.data.Shipments[shipment]
2721		if !ok {
2722			return nil, false, fmt.Errorf("改址失败：运输单号 %q 不存在", shipment)
2723		}
2724		cur := s.effectiveTo(sh)
2725		if expect != cur {
2726			return nil, false, fmt.Errorf("改址失败：预期当前目的站 %q 与运输单 %q 当前有效目的站 %q 不符，整次改址未执行",
2727				expect, shipment, cur)
2728		}
2729		if to == cur {
2730			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与当前有效目的站相同，整次改址未执行", to)
2731		}
2732		if to == sh.From {
2733			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与运输单 %q 源站相同，整次改址未执行", to, shipment)
2734		}
