2736		// 本次集合为受理时的全部未收件，按发运保存顺序。
2737		received := s.receivedUnder(shipment)
2738		members := make([]string, 0, len(sh.Parcels))
2739		for _, pid := range sh.Parcels {
2740			if !received[pid] {
2741				members = append(members, pid)
2742			}
2743		}
2744		if len(members) == 0 {
2745			return nil, false, fmt.Errorf("改址失败：运输单 %q 已全部接收（接收请求号 %q），没有未收件，不能改址", shipment, sh.ReceivedBy)
2746		}
