2748		// 先做全部校验：每件未收件都必须仍归该单在源站站间在途，任一不符整次拒绝。
2749		for _, pid := range members {
2750			p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2751			if p.Status != statusInTransit || p.Station != sh.From {
