2753					pid, p.Station, p.Status, shipment, sh.From)
2754			}
2755		}
2756	
2757		res = &RerouteResult{
2758			Request:  request,
2759			Shipment: shipment,
2760			From:     cur,
2761			To:       to,
2762			Reason:   reason,
2763			Parcels:  members,
2764			Time:     now,
2765		}
2766		s.data.Reroutes[request] = res
2767		sh.Reroutes = append(sh.Reroutes, request)
2768	
2769		// 记录旧值，落盘失败时整体回滚。包裹仍归源站、保持站间在途，只追加改址轨迹。
2770		prev := make(map[string][]Event, len(members))
2771		for _, pid := range members {
2772			p := s.data.Parcels[pid]
2773			prev[pid] = append([]Event(nil), p.Trail...)
2774			p.Trail = append(p.Trail, Event{
2775				Op:       "改址",
2776				Station:  sh.From,
2777				From:     cur,
2778				To:       to,
2779				Shipment: shipment,
2780				Request:  request,
2781				Reason:   reason,
2782				Time:     now,
2783			})
2784		}
2785	
2786		if err := s.save(); err != nil {
2787			delete(s.data.Reroutes, request)
2788			sh.Reroutes = sh.Reroutes[:len(sh.Reroutes)-1]
2789			for pid, old := range prev {
