118		if sh := store.ActiveShipment(cleanIDVal); sh != nil {
119			eff := store.effectiveTo(sh)
120			fmt.Fprintf(stdout, "当前运输单: %s\n当前有效目的站: %s\n", sh.Shipment, eff)
121			if eff != sh.To {
122				fmt.Fprintf(stdout, "原目的站: %s\n", sh.To)
123			}
124		}
125		if f := store.ActiveFreeze(cleanIDVal); f != nil {
126			fmt.Fprintf(stdout, "当前未解除异常: 异常单号: %s    原因: %s    冻结时间: %s\n",
127				f.Incident, f.Reason, f.Time.Format(timeFmt))
128		}
129		fmt.Fprintf(stdout, "轨迹（按提交顺序，共 %d 条）:\n", len(p.Trail))
130		for i, e := range p.Trail {
131			switch e.Op {
132			case "退回":
133				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
134					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
135			case "出站":
136				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
137					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
138			case "回执":
139				revoked := ""
140				if rc := store.ReceiptOf(e.Request); rc != nil && rc.RevokedBy != "" {
141					revoked = fmt.Sprintf("    撤销状态: 已撤销（撤销请求号: %s）", rc.RevokedBy)
142				}
143				if e.Result == resultFailed {
144					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s%s\n",
145						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt), revoked)
146				} else {
147					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s%s\n",
148						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt), revoked)
149				}
150			case "撤销回执":
151				fmt.Fprintf(stdout, "  %d. 操作: 撤销回执    站点: %s    批次号: %s    撤销请求号: %s    原回执请求号: %s    原因: %s    时间: %s\n",
152					i+1, e.Station, e.Batch, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
153			case "冻结":
154				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
155					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
156			case "解除冻结":
157				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
158					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
159			case "收回":
160				fmt.Fprintf(stdout, "  %d. 操作: 收回    站点: %s    批次号: %s    中止请求号: %s    原因: %s    时间: %s\n",
161					i+1, e.Station, e.Batch, e.Request, e.Reason, e.Time.Format(timeFmt))
162			case "续接":
163				fmt.Fprintf(stdout, "  %d. 操作: 续接    站点: %s    原批次号: %s    新批次号: %s    新配送员: %s    续接请求号: %s    原因: %s    时间: %s\n",
164					i+1, e.Station, e.FromBatch, e.Batch, e.Courier, e.Request, e.Reason, e.Time.Format(timeFmt))
165			case "发运":
166				fmt.Fprintf(stdout, "  %d. 操作: 发运    源站: %s    目的站: %s    运输单号: %s    时间: %s\n",
167					i+1, e.From, e.To, e.Shipment, e.Time.Format(timeFmt))
168			case "接收":
169				fmt.Fprintf(stdout, "  %d. 操作: 接收    源站: %s    目的站: %s    运输单号: %s    接收请求号: %s    时间: %s\n",
170					i+1, e.From, e.To, e.Shipment, e.Request, e.Time.Format(timeFmt))
171			case "改址":
172				fmt.Fprintf(stdout, "  %d. 操作: 改址    运输单号: %s    原目的站: %s    新目的站: %s    改址请求号: %s    原因: %s    时间: %s\n",
173					i+1, e.Shipment, e.From, e.To, e.Request, e.Reason, e.Time.Format(timeFmt))
174			default:
175				req := e.Request
176				if req == "" {
177					req = "-"
178				}
179				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
180					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
181			}
182		}
183		return exitOK
184	}
