447			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
448			return exitBusiness
449		}
450	
451		headline := "回执成功"
452		if replayed {
453			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
454			if res.RevokedBy != "" {
455				headline = "回执成功（请求号重复提交，返回首次保存的结果；该回执已撤销，未恢复回执或改变当前状态）"
456			}
457		}
458		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
459			headline, res.Request, res.Batch, res.Parcel, res.Result)
460		if res.Result == resultFailed {
461			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
462		}
463		if res.RevokedBy != "" {
464			fmt.Fprintf(stdout, "撤销状态: 已撤销（撤销请求号: %s）\n", res.RevokedBy)
465		}
466		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
467		return exitOK
468	}
