652	func cmdBatch(dataFile string, argv []string, stdout, stderr io.Writer) int {
653		fs := newFlagSet("batch", stderr)
654		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
655		id := fs.String("id", "", "要查询的配送批次号")
656		if ok, code := parseFlags(fs, argv, stdout, stderr, printBatchHelp); !ok {
657			return code
658		}
659	
660		cleanIDVal, err := cleanID("批次号", *id)
661		if err != nil {
662			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
663			return exitBusiness
664		}
665	
666		store, err := Open(dataFile)
667		if err != nil {
668			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
669			return exitBusiness
670		}
671		b, err := store.BatchQuery(cleanIDVal)
672		if err != nil {
673			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
674			return exitBusiness
675		}
676	
677		// 批次状态优先级：已中止 > 已永久转交 > 已完成 > 配送中。分批续接期间原批次
678		// 仍有待配送件时为配送中；余件全部经回执办结（无待配送件）时为已完成；
679		// 续接转走最后一件待配送件时永久关闭为已转交。
680		ab := store.BatchAbort(cleanIDVal)
681		closedTr := store.BatchTransferSource(cleanIDVal)
682		allTransfers := store.BatchTransfers(cleanIDVal)
683		status := "配送中"
684		switch {
685		case ab != nil:
686			status = "已中止"
687		case closedTr != nil:
688			status = "已转交"
689		case len(store.batchOpen(b)) == 0:
690			status = "已完成"
691		}
692		timeLabel := "出站时间"
693		if b.RelayedFrom != "" {
694			timeLabel = "接手时间"
695		}
696		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
697			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
698		if b.RelayedFrom != "" {
699			src := store.TransferOf(b.RelayRequest)
700			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
701				b.RelayedFrom, src.FromCourier, b.RelayRequest)
702		}
703		if ab != nil {
704			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
705				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
706		}
707		if closedTr != nil {
708			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
709				closedTr.ToBatch, closedTr.ToCourier, closedTr.Request, closedTr.Reason, closedTr.Time.Format(timeFmt))
710		}
711		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
712		for _, pid := range b.Parcels {
713			e, ok := b.Receipts[pid]
714			if !ok || e.RevokedBy != "" {
715				switch {
716				case store.transferOfParcel(cleanIDVal, pid) != nil:
717					tr := store.transferOfParcel(cleanIDVal, pid)
718					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    新配送员: %s    续接请求号: %s    时间: %s\n",
719						pid, tr.ToBatch, tr.ToCourier, tr.Request, tr.Time.Format(timeFmt))
720				case ab != nil:
721					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
722						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
723				case ok:
724					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
725				default:
726					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
727				}
728				continue
729			}
730			if e.Result == resultFailed {
731				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
732					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
733			} else {
734				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
735					pid, e.Result, e.Request, e.Time.Format(timeFmt))
736			}
737		}
738		if len(allTransfers) > 0 {
739			fmt.Fprintf(stdout, "转交记录（%d 次，按提交顺序；转交不计回执）:\n", len(allTransfers))
740			for i, tr := range allTransfers {
741				fmt.Fprintf(stdout, "  %d. 续接请求号: %s    去向批次: %s    新配送员: %s    原因: %s    时间: %s    本次集合（%d 件）:\n",
742					i+1, tr.Request, tr.ToBatch, tr.ToCourier, tr.Reason, tr.Time.Format(timeFmt), len(tr.Parcels))
743				for _, pid := range tr.Parcels {
744					fmt.Fprintf(stdout, "      - %s\n", pid)
745				}
746			}
747		}
748		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
749			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
750			for _, rv := range rvs {
751				fmt.Fprintf(stdout, "  - 撤销请求号: %s    原回执请求号: %s    包裹: %s    批次: %s    原因: %s    时间: %s\n",
752					rv.Request, rv.Receipt, rv.Parcel, rv.Batch, rv.Reason, rv.Time.Format(timeFmt))
753			}
754		}
755		return exitOK
756	}
