298			{Request: "RC1", Batch: "B1", Parcel: "P001", Result: resultSigned},
299			{Request: "RC2", Batch: "B1", Parcel: "P002", Result: resultSigned},
300		}, tClock(2026, 10, 5, 12, 0))
301		if err != nil {
302			t.Fatal(err)
303		}
304		if len(items) != 2 || !items[0].Replayed || !items[0].Revoked || items[1].Replayed || items[1].Revoked {
305			t.Fatalf("导入结果标记不符: %+v", items)
306		}
307		if b, _ := s.BatchQuery("B1"); b.Effective() != 1 || b.Done() {
308			t.Fatalf("进度只计未撤销结果: %+v", b)
309		}
310		// 已撤销回执换内容仍冲突，整份拒绝且新号不占。
311		_, err = s.ImportReceipts([]ReceiptImportRecord{
312			{Request: "RC1", Batch: "B1", Parcel: "P001", Result: resultFailed, Reason: "破损"},
313			{Request: "RC3", Batch: "B1", Parcel: "P001", Result: resultSigned},
314		}, tClock(2026, 10, 5, 13, 0))
315		if err == nil || !strings.Contains(err.Error(), "冲突") {
316			t.Fatalf("已撤销回执换内容应整份拒绝: %v", err)
317		}
318		if _, ok := s.data.Receipts["RC3"]; ok {
319			t.Fatal("整份拒绝时新请求号不得占用")
320		}
321	}
322	
323	func TestRevokeReceiptPersistence(t *testing.T) {
324		s, path := openTempStore(t)
325		setupRevokeBase(t, s)
326		mustReceiptOK(t, s, "RC1", "B1", "P001", resultSigned, "", tClock(2026, 10, 5, 10, 0))
327		t1 := tClock(2026, 10, 5, 11, 0)
328		mustRevoke(t, s, "RV1", "RC1", "误录签收", t1)
329	
330		// 重启后规则不变：状态、进度、撤销事实及去重结果整体保留。
331		s2, err := Open(path)
332		if err != nil {
333			t.Fatalf("重开台账失败: %v", err)
334		}
335		p, _ := s2.Query("P001")
336		if p.Status != statusDelivering || len(p.Trail) != 4 || p.Trail[3].Op != "撤销回执" {
337			t.Fatalf("重开后撤销状态应保留: %+v", p)
338		}
339		res, replayed, err := s2.RevokeReceipt("RV1", "RC1", "误录签收", tClock(2026, 10, 5, 12, 0))
340		if err != nil || !replayed || !res.Time.Equal(t1) {
341			t.Fatalf("重开后重放撤销应返回首次结果: %v replayed=%v", err, replayed)
342		}
343		if _, _, err := s2.RevokeReceipt("RV2", "RC1", "再次撤销", tClock(2026, 10, 5, 12, 0)); err == nil {
344			t.Fatal("重开后仍不得再次撤销同一回执")
345		}
346		if b, _ := s2.BatchQuery("B1"); b.Effective() != 0 {
347			t.Fatalf("重开后有效回执计数应保留: %+v", b)
348		}
349	}
350	
351	func TestRevokeCorruptLinksRejected(t *testing.T) {
352		s, path := openTempStore(t)
353		setupRevokeBase(t, s)
354		mustReceiptOK(t, s, "RC1", "B1", "P001", resultSigned, "", tClock(2026, 10, 5, 10, 0))
355		mustRevoke(t, s, "RV1", "RC1", "误录签收", tClock(2026, 10, 5, 11, 0))
356	
357		raw, err := os.ReadFile(path)
358		if err != nil {
359			t.Fatal(err)
360		}
361		tamper := func(mut func(map[string]any)) string {
362			var doc map[string]any
363			if err := json.Unmarshal(raw, &doc); err != nil {
364				t.Fatal(err)
365			}
366			mut(doc)
367			buf, err := json.Marshal(doc)
368			if err != nil {
369				t.Fatal(err)
370			}
371			bad := path + ".bad"
372			if err := os.WriteFile(bad, buf, 0o644); err != nil {
373				t.Fatal(err)
374			}
375			return bad
376		}
377	
378		// 撤销关联缺失：回执标记了撤销但撤销表为空。
379		bad := tamper(func(doc map[string]any) { doc["revokes"] = map[string]any{} })
380		if _, err := Open(bad); !errors.Is(err, ErrCorrupt) {
381			t.Fatalf("撤销关联缺失应拒绝读写: %v", err)
382		}
383		// 撤销关联不一致：回执的撤销标记被清除。
384		bad = tamper(func(doc map[string]any) {
385			doc["receipts"].(map[string]any)["RC1"].(map[string]any)["revokedBy"] = ""
386		})
387		if _, err := Open(bad); !errors.Is(err, ErrCorrupt) {
388			t.Fatalf("撤销标记不一致应拒绝读写: %v", err)
389		}
390		// 撤销记录指向的原回执不存在。
391		bad = tamper(func(doc map[string]any) {
392			doc["revokes"].(map[string]any)["RV1"].(map[string]any)["receipt"] = "NOPE"
393		})
394		if _, err := Open(bad); !errors.Is(err, ErrCorrupt) {
395			t.Fatalf("撤销引用不存在的回执应拒绝读写: %v", err)
396		}
397		// 撤销轨迹缺失。
398		bad = tamper(func(doc map[string]any) {
399			trail := doc["parcels"].(map[string]any)["P001"].(map[string]any)["trail"].([]any)
400			doc["parcels"].(map[string]any)["P001"].(map[string]any)["trail"] = trail[:len(trail)-1]
401		})
402		if _, err := Open(bad); !errors.Is(err, ErrCorrupt) {
403			t.Fatalf("撤销轨迹缺失应拒绝读写: %v", err)
404		}
405	}
