	out := make([]string, 0, len(b.Parcels))
	for _, pid := range b.Parcels {
		if e, done := b.Receipts[pid]; done && e.RevokedBy == "" {
			continue // 已有有效回执
		}
		transferred := false
		for _, req := range b.Transfers {
			if t := ledger.Transfers[req]; t != nil {
				for _, id := range t.Parcels {
					if id == pid {
						transferred = true
						break
					}
				}
			}
