	if _, errText, code := runCLI(t, dbPath, "receipt-return", "--request", "PR1", "--receipt", "RC1",
		"--reason", "别的原因"); code != exitBusiness || !strings.Contains(errText, "冲突") {
		t.Fatalf("换内容应报冲突(1): code=%d", code)
	}
